create type public.app_role as enum ('admin','hostess','head_waiter','observer');
create type public.reservation_status as enum ('reserved','arrived','cancelled','no_show');
create table public.profiles (id uuid primary key references auth.users on delete cascade, role public.app_role not null default 'observer', first_name text, last_name text, head_waiter_id uuid);
create table public.zones (id uuid primary key default gen_random_uuid(), name text not null, display_order int not null default 0, active boolean not null default true);
create table public.head_waiters (id uuid primary key default gen_random_uuid(), first_name text not null, last_name text not null, color text, active boolean not null default true);
alter table public.profiles add constraint profiles_head_waiter_fk foreign key (head_waiter_id) references public.head_waiters(id) on delete set null;
create table public.tables (id uuid primary key default gen_random_uuid(), number text not null unique, zone_id uuid not null references public.zones(id), head_waiter_id uuid references public.head_waiters(id) on delete set null, standard_capacity smallint not null default 7 check (standard_capacity > 0), status text not null default 'free', position_x numeric not null default 0, position_y numeric not null default 0, active boolean not null default true);
create table public.reservations (id uuid primary key default gen_random_uuid(), table_id uuid not null unique references public.tables(id) on delete cascade, client_name text not null, reserved_people smallint not null check (reserved_people >= 0), planned_arrival timestamptz, status public.reservation_status not null default 'reserved', comment text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.occupancies (table_id uuid primary key references public.tables(id) on delete cascade, present_people smallint not null default 0 check(present_people between 0 and 50), extra_guests smallint not null default 0 check(extra_guests between 0 and 50), comment text, arrived_at timestamptz, updated_at timestamptz not null default now());
create table public.activity_log (id bigint generated always as identity primary key, table_id uuid references public.tables(id) on delete set null, actor_id uuid references auth.users on delete set null, action text not null, before_data jsonb, after_data jsonb, created_at timestamptz not null default now());
create table public.settings (key text primary key, value jsonb not null);
insert into public.settings(key,value) values ('thresholds','{"lightOverloadFrom":8,"overloadFrom":10}');
create function public.current_role() returns public.app_role language sql stable security definer set search_path=public as $$ select role from public.profiles where id=auth.uid() $$;
create function public.can_edit_table(p_table uuid) returns boolean language sql stable security definer set search_path=public as $$ select public.current_role()='admin' or (public.current_role()='head_waiter' and exists(select 1 from public.tables t join public.profiles p on p.head_waiter_id=t.head_waiter_id where t.id=p_table and p.id=auth.uid())) $$;
create function public.touch_occupancy() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
create trigger occupancy_updated before update on public.occupancies for each row execute function public.touch_occupancy();
create function public.log_occupancy() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.activity_log(table_id,actor_id,action,before_data,after_data) values(coalesce(new.table_id,old.table_id),auth.uid(),'occupancy_changed',to_jsonb(old),to_jsonb(new)); return coalesce(new,old); end $$;
create trigger occupancy_history after insert or update or delete on public.occupancies for each row execute function public.log_occupancy();
alter table public.zones enable row level security; alter table public.head_waiters enable row level security; alter table public.tables enable row level security; alter table public.reservations enable row level security; alter table public.occupancies enable row level security; alter table public.activity_log enable row level security; alter table public.settings enable row level security;
create policy "authenticated read" on public.zones for select to authenticated using (true); create policy "authenticated read" on public.head_waiters for select to authenticated using (true); create policy "authenticated read" on public.tables for select to authenticated using (true); create policy "authenticated read" on public.reservations for select to authenticated using (true); create policy "authenticated read" on public.occupancies for select to authenticated using (true); create policy "authenticated read" on public.activity_log for select to authenticated using (true); create policy "authenticated read" on public.settings for select to authenticated using (true);
create policy "admin manages zones" on public.zones for all to authenticated using (public.current_role()='admin') with check (public.current_role()='admin'); create policy "admin manages waiters" on public.head_waiters for all to authenticated using (public.current_role()='admin') with check (public.current_role()='admin'); create policy "admin manages tables" on public.tables for all to authenticated using (public.current_role()='admin') with check (public.current_role()='admin'); create policy "arrival managers reservations" on public.reservations for all to authenticated using (public.current_role() in ('admin','hostess')) with check (public.current_role() in ('admin','hostess'));
create policy "table editors manage occupancy" on public.occupancies for all to authenticated using (public.can_edit_table(table_id) or public.current_role()='hostess') with check (public.can_edit_table(table_id) or public.current_role()='hostess');
alter publication supabase_realtime add table public.occupancies, public.reservations, public.tables;
